// git_submodule_macros.rs - Git submodule to macro resolution system
// Generated by step4_bootstrap - Git Submodule Integration

use std::fs;
use std::path::Path;
use anyhow::Result;

pub fn resolve_submodule_path(submodule_name: &str) -> String {
    format!("../{}", submodule_name)
}

pub fn find_cargo_tomls(submodule_path: &str) -> Result<Vec<String>> {
    let mut cargo_tomls = Vec::new();
    
    fn scan_dir(dir: &Path, cargo_tomls: &mut Vec<String>) -> Result<()> {
        if !dir.exists() { return Ok(()); }
        
        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();
            
            if path.is_file() && path.file_name() == Some("Cargo.toml".as_ref()) {
                if let Some(path_str) = path.to_str() {
                    cargo_tomls.push(path_str.to_string());
                }
            } else if path.is_dir() {
                scan_dir(&path, cargo_tomls)?;
            }
        }
        Ok(())
    }
    
    scan_dir(Path::new(submodule_path), &mut cargo_tomls)?;
    Ok(cargo_tomls)
}

pub fn extract_crate_name_from_cargo_toml(cargo_toml_path: &str) -> Result<String> {
    let content = fs::read_to_string(cargo_toml_path)?;
    
    for line in content.lines() {
        if line.starts_with("name = ") {
            return Ok(line.split('"').nth(1).unwrap_or("unknown").to_string());
        }
    }
    
    Ok("unknown".to_string())
}

#[macro_export]
macro_rules! git_sub {
    ($submodule:expr) => {{
        let submodule_path = resolve_submodule_path($submodule);
        let cargo_tomls = find_cargo_tomls(&submodule_path).unwrap_or_default();
        
        let mut crates = Vec::new();
        for cargo_toml in cargo_tomls {
            if let Ok(crate_name) = extract_crate_name_from_cargo_toml(&cargo_toml) {
                let crate_info = mkcrate!(&crate_name);
                crates.push(crate_info);
            }
        }
        
        if crates.len() > 5 {
            println!("🔗 git-sub-{}! → {} crates", $submodule, crates.len());
        }
        crates
    }};
}
